// Generated by scaffold-realtime-gateway
// REALTIME capability — live-updates gateway. Cookie-JWT handshake auth (RULE-B7).
import {
  WebSocketGateway, WebSocketServer, SubscribeMessage,
  OnGatewayConnection, OnGatewayDisconnect, MessageBody, ConnectedSocket,
} from '@nestjs/websockets';
import { Logger } from '@nestjs/common';
import { Server, Socket } from 'socket.io';
import * as cookie from 'cookie';
import * as jwt from 'jsonwebtoken';
import { RoomMembershipService } from '../room-membership/room-membership.service';

type AuthedSocket = Socket & { data: { user?: { id: string; role?: unknown } } };

@WebSocketGateway({ cors: { origin: (process.env.ALLOW_ORIGINS || '').split(',').filter(Boolean), credentials: true }, namespace: '/live' })
export class LiveUpdatesGateway implements OnGatewayConnection, OnGatewayDisconnect {
  @WebSocketServer() server!: Server;
  private readonly logger = new Logger('LiveUpdatesGateway');

  constructor(private readonly membership: RoomMembershipService) {}

  // RULE-B7: authenticate the socket from the httpOnly JWT cookie on connect.
  // No valid token → disconnect immediately (never trust an unauthenticated socket).
  handleConnection(client: AuthedSocket): void {
    try {
      const raw = client.handshake.headers.cookie || '';
      const token = cookie.parse(raw)['access_token'] ||
        (client.handshake.auth && (client.handshake.auth as { token?: string }).token);
      const secret = process.env.JWT_SECRET;
      if (!token || !secret) { client.disconnect(true); return; }
      const payload = jwt.verify(token, secret) as { id?: string; sub?: string; role?: unknown };
      const id = payload.id || payload.sub;
      if (!id) { client.disconnect(true); return; }
      client.data.user = { id, role: payload.role };
      this.logger.log('connected ' + id + ' (' + client.id + ')');
    } catch {
      client.disconnect(true);
    }
  }

  handleDisconnect(client: AuthedSocket): void {
    this.logger.log('disconnected ' + client.id);
  }

  // Join is membership-gated — composes the room-membership capability (RBAC).
  @SubscribeMessage('room.join')
  async onRoomJoin(@ConnectedSocket() client: AuthedSocket, @MessageBody() body: { roomId: string }) {
    const user = client.data.user;
    if (!user || !body || !body.roomId) return { ok: false, error: 'unauthenticated_or_bad_request' };
    const allowed = await this.membership.isMember(body.roomId, user.id);
    if (!allowed) return { ok: false, error: 'not_a_member' };
    await client.join(body.roomId);
    return { ok: true, roomId: body.roomId };
  }

  @SubscribeMessage('room.leave')
  async onRoomLeave(@ConnectedSocket() client: AuthedSocket, @MessageBody() body: { roomId: string }) {
    if (body && body.roomId) await client.leave(body.roomId);
    return { ok: true };
  }

  @SubscribeMessage('subscribe')
  async onSubscribe(@ConnectedSocket() client: AuthedSocket, @MessageBody() body: Record<string, unknown>) {
    const user = client.data.user;
    if (!user) return { ok: false, error: 'unauthenticated' };
    const roomId = body && (body['roomId'] as string);
    // Broadcast to the room when room-scoped, else echo to the sender.
    const payload = { ...body, from: user.id, event: 'subscribe', at: new Date().toISOString() };
    if (roomId) {
      const allowed = await this.membership.isMember(roomId, user.id);
      if (!allowed) return { ok: false, error: 'not_a_member' };
      this.server.to(roomId).emit('subscribe', payload);
    } else {
      client.emit('subscribe', payload);
    }
    return { ok: true };
  }

  @SubscribeMessage('unsubscribe')
  async onUnsubscribe(@ConnectedSocket() client: AuthedSocket, @MessageBody() body: Record<string, unknown>) {
    const user = client.data.user;
    if (!user) return { ok: false, error: 'unauthenticated' };
    const roomId = body && (body['roomId'] as string);
    // Broadcast to the room when room-scoped, else echo to the sender.
    const payload = { ...body, from: user.id, event: 'unsubscribe', at: new Date().toISOString() };
    if (roomId) {
      const allowed = await this.membership.isMember(roomId, user.id);
      if (!allowed) return { ok: false, error: 'not_a_member' };
      this.server.to(roomId).emit('unsubscribe', payload);
    } else {
      client.emit('unsubscribe', payload);
    }
    return { ok: true };
  }
}
